  final body = syncBodyOrError(SyncHttpClient.get(
    '$base/wit/fields?api-version=$_apiVersion',
    headers: c.headers,
  ));
  if (syncTryDecode(body) is! Map) return 'null';
  return jsonEncode(findAdoFieldCode(body, wanted));
}

