    final response = await dio.request<String>(
      project == null ? buildUrl(path) : buildProjectUrl(project, path),
      data: body,
      queryParameters: {'api-version': apiVersion},
      options: Options(
        method: method,
        headers: {...authHeaders, 'Content-Type': contentType},
