  /// Performs a GET, merging `api-version` into the query parameters.
  @override
  Future<String> get(
    String path, {
    Map<String, dynamic>? queryParams,
    Map<String, String>? extra,
  }) =>
      super.get(
        path,
        queryParams: {...?queryParams, 'api-version': apiVersion},
