  final existing = syncTryDecode(syncBodyOrError(SyncHttpClient.get(
      '${c.baseUrl}/wit/workitems/$id?\$expand=relations'
      '&api-version=$_apiVersion',
      headers: c.headers)));
  if (!adoHasAttachment(existing, name)) {
